async function submitAuth(e){e.preventDefault();const form=e.currentTarget,mode=form.dataset.mode,error=$('#auth-error'),button=$('button[type=submit]',form);error.textContent='';const password=$('#auth-password').value;if(mode==='register'&&password!==$('#auth-confirm').value){error.textContent='As senhas precisam ser iguais.';$('#auth-confirm').focus();return}const values={email:$('#auth-email').value,password,avatar:state.avatar,...(mode==='register'?{name:$('#auth-name').value}:{})};button.disabled=true;button.textContent=mode==='register'?'Criando sua conta…':'Entrando…';try{const d=await post(`/api/auth/${mode}`,values);state.user=d.user;state.avatar=d.user.avatar;store.set('ad_avatar',state.avatar);loadPersonal();toast(mode==='register'?'Sua conta foi criada!':'Bem-vindo de volta!');nav('home')}catch(err){if(form.isConnected){error.textContent=err.message;button.disabled=false;button.textContent=mode==='register'?'Começar minha jornada →':'Entrar no AnimeDragon →'}}}
