function setModal(content,watch=false){if(watchController){watchController.destroy();watchController=null;}$('#modal-root').innerHTML=`<div class="modal-back ${watch?'watch-back':''}"><section class="modal ${watch?'watch-modal':''}" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="modal-navigation"><button class="modal-back-button" id="modal-back">${icon('left')} Voltar</button><span>ANIMEDRAGON</span></div>${content}</section></div>`;document.body.classList.add('modal-open');$('#app').inert=true;$('#modal-root .modal').focus();$('#modal-root .modal-back').onclick=e=>{if(e.target===e.currentTarget)closeModal()};$('#modal-back').onclick=()=>{if($('#playback-body')&&state.details){openDetails(state.details.id,state.season,null,true);return}const previous=detailTrail.pop();if(previous)openDetails(previous.id,previous.season,null,true);else closeModal()};}
